int
esl_msa_AddGF(ESL_MSA *msa, char *tag, esl_pos_t taglen, char *value, esl_pos_t vlen)
{
  int status;
  int i;

  if (msa->ngf == 0 && msa->gc_idx == NULL)
    msa->gc_idx = esl_keyhash_Create();

  if (msa->ngf == msa->alloc_ngf) {
    void *tmp;
    ESL_RALLOC(msa->gf_tag, tmp, sizeof(char *) * (msa->alloc_ngf + 16));
    ESL_RALLOC(msa->gf, tmp, sizeof(char *) * (msa->alloc_ngf + 16));
    msa->alloc_ngf += 16;
  }

  if (taglen >= 0) status = esl_memstrdup(tag, taglen, &(msa->gf_tag[msa->ngf]));
  else status = esl_strdup( tag, -1, &(msa->gf_tag[msa->ngf]));
  if (status != eslOK) goto ERROR;

  if (vlen >= 0) status = esl_memstrdup(value, vlen, &(msa->gf[msa->ngf]));
  else status = esl_strdup( value, -1, &(msa->gf[msa->ngf]));
  if (status != eslOK) goto ERROR;

  if (msa->gc_idx != NULL)
    esl_keyhash_Store(msa->gc_idx, msa->gf_tag[msa->ngf], -1, &i);

  msa->ngf++;
  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_AddGS(ESL_MSA *msa, char *tag, esl_pos_t taglen, int sqidx, char *value, esl_pos_t vlen)
{
  int status;
  int tagidx;
  int i;

  if (msa->gs_idx == NULL)
    msa->gs_idx = esl_keyhash_Create();

  status = esl_keyhash_Store(msa->gs_idx, tag, taglen, &tagidx);
  if (status == eslOK && tagidx == msa->ngs) {
    void *tmp;
    ESL_RALLOC(msa->gs_tag, tmp, sizeof(char *) * (msa->ngs+1));
    ESL_RALLOC(msa->gs, tmp, sizeof(char **) * (msa->ngs+1));

    if (taglen >= 0) status = esl_memstrdup(tag, taglen, &(msa->gs_tag[tagidx]));
    else status = esl_strdup( tag, -1, &(msa->gs_tag[tagidx]));
    if (status != eslOK) goto ERROR;

    ESL_ALLOC(msa->gs[tagidx], sizeof(char *) * msa->sqalloc);
    for (i = 0; i < msa->sqalloc; i++)
      msa->gs[tagidx][i] = NULL;

    msa->ngs++;
  }
  else if (status != eslOK) goto ERROR;

  if (vlen >= 0) status = esl_memstrdup(value, vlen, &(msa->gs[tagidx][sqidx]));
  else status = esl_strdup( value, -1, &(msa->gs[tagidx][sqidx]));
  if (status != eslOK) goto ERROR;

  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_AppendGC(ESL_MSA *msa, char *tag, char *value)
{
  int status;
  int tagidx;
  int i;

  if (msa->gc_idx == NULL)
    msa->gc_idx = esl_keyhash_Create();

  status = esl_keyhash_Store(msa->gc_idx, tag, -1, &tagidx);
  if (status == eslOK && tagidx == msa->ngc) {
    void *tmp;
    ESL_RALLOC(msa->gc_tag, tmp, sizeof(char *) * (msa->ngc+1));
    ESL_RALLOC(msa->gc, tmp, sizeof(char *) * (msa->ngc+1));

    if ((status = esl_strdup(tag, -1, &(msa->gc_tag[tagidx]))) != eslOK) goto ERROR;
    msa->gc[tagidx] = NULL;
    msa->ngc++;
  }
  else if (status != eslOK) goto ERROR;

  if (msa->gc[tagidx] == NULL) {
    ESL_ALLOC(msa->gc[tagidx], sizeof(char) * (msa->alen + 1));
    for (i = 0; i < msa->alen; i++) msa->gc[tagidx][i] = '.';
    msa->gc[tagidx][msa->alen] = '\0';
  }

  if (esl_strmapcat(msa->abc ? msa->abc->inmap : NULL, &(msa->gc[tagidx]), -1, value, -1) != eslOK) goto ERROR;
  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_AppendGR(ESL_MSA *msa, char *tag, int sqidx, char *value)
{
  int tagidx;
  int i;
  int status;

  if (msa->gr_idx == NULL)
    msa->gr_idx = esl_keyhash_Create();

  status = esl_keyhash_Store(msa->gr_idx, tag, -1, &tagidx);
  if (status == eslOK && tagidx == msa->ngr) {
    void *tmp;
    ESL_RALLOC(msa->gr_tag, tmp, sizeof(char *) * (msa->ngr+1));
    ESL_RALLOC(msa->gr, tmp, sizeof(char **) * (msa->ngr+1));

    if ((status = esl_strdup(tag, -1, &(msa->gr_tag[tagidx]))) != eslOK) goto ERROR;

    ESL_ALLOC(msa->gr[tagidx], sizeof(char *) * msa->sqalloc);
    for (i = 0; i < msa->sqalloc; i++)
      msa->gr[tagidx][i] = NULL;

    msa->ngr++;
  }
  else if (status != eslOK) goto ERROR;

  if (msa->gr[tagidx][sqidx] == NULL) {
    ESL_ALLOC(msa->gr[tagidx][sqidx], sizeof(char) * (msa->alen+1));
    for (i = 0; i < msa->alen; i++) msa->gr[tagidx][sqidx][i] = '.';
    msa->gr[tagidx][sqidx][msa->alen] = '\0';
  }

  if (esl_strmapcat(msa->abc ? msa->abc->inmap : NULL, &(msa->gr[tagidx][sqidx]), -1, value, -1) != eslOK) goto ERROR;
  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_CheckUniqueNames(const ESL_MSA *msa)
{
  ESL_KEYHASH *kh = NULL;
  int idx;
  int status;

  if ((kh = esl_keyhash_Create()) == NULL) { status = eslEMEM; goto ERROR; }

  for (idx = 0; idx < msa->nseq; idx++) {
    status = esl_keyhash_Store(kh, msa->sqname[idx], -1, NULL);
    if (status == eslEDUP) ESL_XFAIL(eslEDUP, NULL, "sequence name %s occurs more than once in MSA", msa->sqname[idx]);
    if (status != eslOK) goto ERROR;
  }

  esl_keyhash_Destroy(kh);
  return eslOK;

 ERROR:
  if (kh) esl_keyhash_Destroy(kh);
  return status;
}

int
esl_msa_SetSeqDup(ESL_MSA *msa, int idx)
{
  if (msa->flags & eslMSA_DIGITAL) ESL_EXCEPTION(eslEINVAL, "can't set seq in digital mode MSA; use esl_msa_SetSeqDup_D()");
  if (idx >= msa->nseq) ESL_EXCEPTION(eslEINVAL, "seq idx %d exceeds current # of seqs %d", idx, msa->nseq);
  if (msa->aseq[idx] != NULL) { free(msa->aseq[idx]); msa->aseq[idx] = NULL; }

  return eslOK;
}

int
esl_msa_SetSeq(ESL_MSA *msa, int idx, const char *seq)
{
  int64_t n;
  int status;

  if (msa->flags & eslMSA_DIGITAL) ESL_EXCEPTION(eslEINVAL, "can't set seq in digital mode MSA; use esl_msa_SetDigitized()");
  if (idx >= msa->nseq) ESL_EXCEPTION(eslEINVAL, "seq idx %d exceeds current # of seqs %d", idx, msa->nseq);

  if (msa->aseq[idx] != NULL) { free(msa->aseq[idx]); msa->aseq[idx] = NULL; }

  n = strlen(seq);
  ESL_ALLOC(msa->aseq[idx], sizeof(char) * (n+1));
  strcpy(msa->aseq[idx], seq);

  msa->sqlen[idx] = n;
  if (msa->alen == -1 || msa->alen < n) msa->alen = n;
  if (idx == msa->nseq-1) msa->alen = n;

  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_SetDigitized(ESL_MSA *msa, int idx, const ESL_DSQ *dsq)
{
  int64_t n;
  int status;

  if (! (msa->flags & eslMSA_DIGITAL)) ESL_EXCEPTION(eslEINVAL, "can't set digitized seq in text mode MSA");
  if (idx >= msa->nseq) ESL_EXCEPTION(eslEINVAL, "seq idx %d exceeds current # of seqs %d", idx, msa->nseq);

  if (msa->ax[idx] != NULL) { free(msa->ax[idx]); msa->ax[idx] = NULL; }

  n = esl_abc_dsqlen(dsq);
  ESL_ALLOC(msa->ax[idx], sizeof(ESL_DSQ) * (n+2));
  memcpy(msa->ax[idx], dsq, sizeof(ESL_DSQ) * (n+2));

  msa->sqlen[idx] = n;
  if (msa->alen == -1 || msa->alen < n) msa->alen = n;
  if (idx == msa->nseq-1) msa->alen = n;

  return eslOK;

 ERROR:
  return status;
}

int
esl_msa_MinimGaps(ESL_MSA *msa, char *errbuf, const char *gaps, int consider_rf)
{
  int *useme = NULL;
  int apos, idx;
  int64_t nseqgap;
  int status;

  if (msa->nseq == 0) return eslOK;

  ESL_ALLOC(useme, sizeof(int) * (msa->alen+1));

  for (apos = 1; apos <= msa->alen; apos++) {
    for (nseqgap = 0, idx = 0; idx < msa->nseq; idx++) {
      if (msa->flags & eslMSA_DIGITAL) {
        if (esl_abc_XIsGap(msa->abc, msa->ax[idx][apos])) nseqgap++;
      } else {
        if (strchr(gaps, msa->aseq[idx][apos-1]) != NULL) nseqgap++;
      }
    }

    if (nseqgap == msa->nseq &&
        (! consider_rf || msa->rf == NULL || esl_abc_CIsGap(msa->rf[apos-1])))
      useme[apos] = FALSE;
    else
      useme[apos] = TRUE;
  }

  if ((status = esl_msa_ColumnSubset(msa, errbuf, useme)) != eslOK) goto ERROR;

  free(useme);
  return eslOK;

 ERROR:
  if (useme) free(useme);
  return status;
}

int
esl_msa_NoGaps(ESL_MSA *msa, char *errbuf, const char *gaps)
{
  int *useme = NULL;
  int apos, idx;
  int status;

  if (msa->nseq == 0) return eslOK;

  ESL_ALLOC(useme, sizeof(int) * (msa->alen+1));

  for (apos = 1; apos <= msa->alen; apos++) {
    useme[apos] = TRUE;
    for (idx = 0; idx < msa->nseq; idx++) {
      if (msa->flags & eslMSA_DIGITAL) {
        if (esl_abc_XIsGap(msa->abc, msa->ax[idx][apos])) { useme[apos] = FALSE; break; }
      } else {
        if (strchr(gaps, msa->aseq[idx][apos-1]) != NULL) { useme[apos] = FALSE; break; }
      }
    }
  }

  if ((status = esl_msa_ColumnSubset(msa, errbuf, useme)) != eslOK) goto ERROR;

  free(useme);
  return eslOK;

 ERROR:
  if (useme) free(useme);
  return status;
}

int
esl_msa_SymConvert(ESL_MSA *msa, const char *oldsyms, const char *newsyms)
{
  int64_t apos;
  int idx, i;

  if (msa->flags & eslMSA_DIGITAL) ESL_EXCEPTION(eslEINVAL, "can't SymConvert on digitized alignment");

  for (idx = 0; idx < msa->nseq; idx++)
    for (apos = 0; apos < msa->alen; apos++)
      for (i = 0; oldsyms[i] != '\0'; i++)
        if (msa->aseq[idx][apos] == oldsyms[i])
          msa->aseq[idx][apos] = newsyms[i];

  for (apos = 0; msa->rf && apos < msa->alen; apos++)
    for (i = 0; oldsyms[i] != '\0'; i++)
      if (msa->rf[apos] == oldsyms[i])
        msa->rf[apos] = newsyms[i];

  for (apos = 0; msa->ss_cons && apos < msa->alen; apos++)
    for (i = 0; oldsyms[i] != '\0'; i++)
      if (msa->ss_cons[apos] == oldsyms[i])
        msa->ss_cons[apos] = newsyms[i];

  for (apos = 0; msa->sa_cons && apos < msa->alen; apos++)
    for (i = 0; oldsyms[i] != '\0'; i++)
      if (msa->sa_cons[apos] == oldsyms[i])
        msa->sa_cons[apos] = newsyms[i];

  for (idx = 0; msa->ss && msa->ss[idx] && idx < msa->nseq; idx++)
    for (apos = 0; apos < msa->alen; apos++)
      for (i = 0; oldsyms[i] != '\0'; i++)
        if (msa->ss[idx][apos] == oldsyms[i])
          msa->ss[idx][apos] = newsyms[i];

  for (idx = 0; msa->sa && msa->sa[idx] && idx < msa->nseq; idx++)
    for (apos = 0; apos < msa->alen; apos++)
      for (i = 0; oldsyms[i] != '\0'; i++)
        if (msa->sa[idx][apos] == oldsyms[i])
          msa->sa[idx][apos] = newsyms[i];

  for (idx = 0; msa->pp && msa->pp[idx] && idx < msa->nseq; idx++)
    for (apos = 0; apos < msa->alen; apos++)
      for (i = 0; oldsyms[i] != '\0'; i++)
        if (msa->pp[idx][apos] == oldsyms[i])
          msa->pp[idx][apos] = newsyms[i];

  return eslOK;
}

int
esl_msa_AddSeq(ESL_MSA *msa, const char *seqname, const char *seq)
{
  int idx;
  int status;

  if (msa->nseq == msa->sqalloc && (status = esl_msa_Expand(msa)) != eslOK) return status;

  idx = msa->nseq;
  if ((status = esl_msa_SetSeqName(msa, idx, seqname, -1)) != eslOK) return status;
  if ((status = esl_msa_SetSeq(msa, idx, seq)) != eslOK) return status;

  msa->wgt[idx] = 1.0;
  msa->nseq++;

  return eslOK;
}

int
esl_msa_AddDigitizedSeq(ESL_MSA *msa, const char *seqname, const ESL_DSQ *dsq)
{
  int idx;
  int status;

  if (! (msa->flags & eslMSA_DIGITAL)) ESL_EXCEPTION(eslEINVAL, "digital sequence added to text mode alignment");
  if (msa->nseq == msa->sqalloc && (status = esl_msa_Expand(msa)) != eslOK) return status;

  idx = msa->nseq;
  if ((status = esl_msa_SetSeqName(msa, idx, seqname, -1)) != eslOK) return status;
  if ((status = esl_msa_SetDigitized(msa, idx, dsq)) != eslOK) return status;

  msa->wgt[idx] = 1.0;
  msa->nseq++;

  return eslOK;
}

int
esl_msa_ReverseComplement(ESL_MSA *msa)
{
  ESL_SQ *sq = NULL;
  int i;
  int status;

  if (! (msa->flags & eslMSA_DIGITAL)) ESL_EXCEPTION(eslEINVAL, "can't take reverse complement of text mode alignment");

  sq = esl_sq_CreateDigital(msa->abc);

  for (i = 0; i < msa->nseq; i++) {
    if ((status = esl_sq_SetSource(sq, msa->sqname[i])) != eslOK) goto ERROR;
    if ((status = esl_sq_GrowTo(sq, msa->alen)) != eslOK) goto ERROR;

    memcpy(sq->dsq, msa->ax[i], (msa->alen+2) * sizeof(ESL_DSQ));
    sq->n = msa->alen;

    if ((status = esl_sq_ReverseComplement(sq)) != eslOK) goto ERROR;
    memcpy(msa->ax[i], sq->dsq, (msa->alen+2) * sizeof(ESL_DSQ));
  }

  esl_sq_Destroy(sq);
  return eslOK;

 ERROR:
  if (sq) esl_sq_Destroy(sq);
  return status;
}

int
esl_msa_Hash(const ESL_MSA *msa)
{
  int i;
  int status;

  if (msa->index) esl_keyhash_Reuse(msa->index);

  for (i = 0; i < msa->nseq; i++)
    if ((status = esl_keyhash_Store(msa->index, msa->sqname[i], -1, NULL)) != eslOK) return status;

  return eslOK;
}

int
esl_msa_FlushLeftInserts(ESL_MSA *msa)
{
  int *nins = NULL;
  int *first = NULL;
  int *moved = NULL;
  int idx, apos, npos;
  int ninserts;
  int status;

  if (msa->rf == NULL) return eslOK;

  ESL_ALLOC(nins, sizeof(int) * (msa->alen+1));
  ESL_ALLOC(first, sizeof(int) * (msa->alen+1));
  ESL_ALLOC(moved, sizeof(int) * (msa->alen+1));

  for (apos = 0; apos <= msa->alen; apos++)
    nins[apos] = first[apos] = moved[apos] = 0;

  ninserts = 0;
  for (apos = 0; apos < msa->alen; apos++)
    if (esl_abc_CIsGap(msa->rf[apos])) {
      if (apos == 0 || ! esl_abc_CIsGap(msa->rf[apos-1]))
        first[ninserts++] = apos;
      nins[ninserts-1]++;
    }

  for (idx = 0; idx < msa->nseq; idx++) {
    for (ninserts = 0, apos = 0; apos < msa->alen; apos++)
      if (esl_abc_CIsGap(msa->rf[apos])) {
        if (apos == 0 || ! esl_abc_CIsGap(msa->rf[apos-1]))
          ninserts++;
        if (! esl_abc_XIsGap(msa->abc, msa->ax[idx][apos+1]))
          moved[ninserts-1]++;
      }

    for (ninserts = 0, apos = 0; apos < msa->alen; apos++)
      if (esl_abc_CIsGap(msa->rf[apos])) {
        if (apos == 0 || ! esl_abc_CIsGap(msa->rf[apos-1]))
          ninserts++;
        npos = first[ninserts-1] + moved[ninserts-1];
        if (! esl_abc_XIsGap(msa->abc, msa->ax[idx][apos+1])) {
          if (npos != apos) {
            msa->ax[idx][npos+1] = msa->ax[idx][apos+1];
            msa->ax[idx][apos+1] = esl_abc_XGetGap(msa->abc);
          }
          moved[ninserts-1]++;
        }
      }

    for (ninserts = 0; ninserts < msa->alen; ninserts++)
      moved[ninserts] = 0;
  }

  free(nins);
  free(first);
  free(moved);
  return eslOK;

 ERROR:
  if (nins) free(nins);
  if (first) free(first);
  if (moved) free(moved);
  return status;
}

int
esl_msa_SequenceSubset(const ESL_MSA *msa, const int *useme, ESL_MSA **ret_new)
{
  ESL_MSA *new = NULL;
  int nnew;
  int oidx, nidx;
  int i;
  int status;

  *ret_new = NULL;

  nnew = 0;
  for (oidx = 0; oidx < msa->nseq; oidx++)
    if (useme[oidx]) nnew++;
  if (nnew == 0) ESL_EXCEPTION(eslEINVAL, "No sequences selected");

  if ((new = esl_msa_Create(nnew, -1)) == NULL) { status = eslEMEM; goto ERROR; }

  if (msa->flags & eslMSA_DIGITAL) {
    if ((status = esl_msa_Digitize(msa->abc, new, NULL)) != eslOK) goto ERROR;
  }

  for (nidx = 0, oidx = 0; oidx < msa->nseq; oidx++)
    if (useme[oidx]) {
      if (msa->flags & eslMSA_DIGITAL) {
        if ((status = esl_msa_SetDigitized(new, nidx, msa->ax[oidx])) != eslOK) goto ERROR;
      } else {
        if ((status = esl_msa_SetSeq(new, nidx, msa->aseq[oidx])) != eslOK) goto ERROR;
      }

      if ((status = esl_msa_SetSeqName(new, nidx, msa->sqname[oidx], -1)) != eslOK) goto ERROR;
      new->wgt[nidx] = msa->wgt[oidx];

      if (msa->sqacc && msa->sqacc[oidx])
        if ((status = esl_msa_SetSeqAccession(new, nidx, msa->sqacc[oidx], -1)) != eslOK) goto ERROR;
      if (msa->sqdesc && msa->sqdesc[oidx])
        if ((status = esl_msa_SetSeqDescription(new, nidx, msa->sqdesc[oidx], -1)) != eslOK) goto ERROR;
      if (msa->ss && msa->ss[oidx])
        if ((status = esl_msa_AddGR(new, "SS", nidx, msa->ss[oidx], -1)) != eslOK) goto ERROR;
      if (msa->sa && msa->sa[oidx])
        if ((status = esl_msa_AddGR(new, "SA", nidx, msa->sa[oidx], -1)) != eslOK) goto ERROR;
      if (msa->pp && msa->pp[oidx])
        if ((status = esl_msa_AddGR(new, "PP", nidx, msa->pp[oidx], -1)) != eslOK) goto ERROR;

      for (i = 0; i < msa->ngr; i++)
        if (msa->gr[i][oidx])
          if ((status = esl_msa_AddGR(new, msa->gr_tag[i], nidx, msa->gr[i][oidx], -1)) != eslOK) goto ERROR;

      for (i = 0; i < msa->ngs; i++)
        if (msa->gs[i][oidx])
          if ((status = esl_msa_AddGS(new, msa->gs_tag[i], -1, nidx, msa->gs[i][oidx], -1)) != eslOK) goto ERROR;

      nidx++;
    }

  new->nseq = nnew;
  new->alen = msa->alen;
  new->flags = msa->flags;

  if (msa->name) esl_msa_SetName(new, msa->name, -1);
  if (msa->desc) esl_msa_SetDesc(new, msa->desc, -1);
  if (msa->acc) esl_msa_SetAccession(new, msa->acc, -1);
  if (msa->au) esl_msa_SetAuthor(new, msa->au, -1);
  if (msa->ss_cons) esl_strdup(msa->ss_cons, -1, &(new->ss_cons));
  if (msa->sa_cons) esl_strdup(msa->sa_cons, -1, &(new->sa_cons));
  if (msa->pp_cons) esl_strdup(msa->pp_cons, -1, &(new->pp_cons));
  if (msa->rf) esl_strdup(msa->rf, -1, &(new->rf));
  if (msa->mm) esl_strdup(msa->mm, -1, &(new->mm));

  for (i = 0; i < eslMSA_NCUTS; i++) {
    new->cutoff[i] = msa->cutoff[i];
    new->cutset[i] = msa->cutset[i];
  }

  for (i = 0; i < msa->ncomment; i++)
    if ((status = esl_msa_AddComment(new, msa->comment[i], -1)) != eslOK) goto ERROR;

  for (i = 0; i < msa->ngf; i++)
    if ((status = esl_msa_AddGF(new, msa->gf_tag[i], -1, msa->gf[i], -1)) != eslOK) goto ERROR;

  for (i = 0; i < msa->ngc; i++)
    if ((status = esl_msa_AppendGC(new, msa->gc_tag[i], msa->gc[i])) != eslOK) goto ERROR;

  *ret_new = new;
  return eslOK;

 ERROR:
  if (new) esl_msa_Destroy(new);
  *ret_new = NULL;
  return status;
}

int
esl_msa_ColumnSubset(ESL_MSA *msa, char *errbuf, const int *useme)
{
  int64_t opos;
  int64_t npos;
  int idx, i;
  int status;

  if (msa->nseq == 0) return eslOK;

  npos = 0;
  for (opos = 1; opos <= msa->alen; opos++)
    if (useme[opos]) npos++;
  if (npos == 0) ESL_FAIL(eslEINVAL, errbuf, "No columns selected");

  for (idx = 0; idx < msa->nseq; idx++) {
    if (msa->flags & eslMSA_DIGITAL) {
      for (opos = 1, npos = 1; opos <= msa->alen; opos++)
        if (useme[opos]) msa->ax[idx][npos++] = msa->ax[idx][opos];
      msa->ax[idx][npos] = eslDSQ_SENTINEL;
    } else {
      for (opos = 0, npos = 0; opos < msa->alen; opos++)
        if (useme[opos+1]) msa->aseq[idx][npos++] = msa->aseq[idx][opos];
      msa->aseq[idx][npos] = '\0';
    }

    if (msa->ss && msa->ss[idx]) {
      for (opos = 0, npos = 0; opos < msa->alen; opos++)
        if (useme[opos+1]) msa->ss[idx][npos++] = msa->ss[idx][opos];
      msa->ss[idx][npos] = '\0';
    }

    if (msa->sa && msa->sa[idx]) {
      for (opos = 0, npos = 0; opos < msa->alen; opos++)
        if (useme[opos+1]) msa->sa[idx][npos++] = msa->sa[idx][opos];
      msa->sa[idx][npos] = '\0';
    }

    if (msa->pp && msa->pp[idx]) {
      for (opos = 0, npos = 0; opos < msa->alen; opos++)
        if (useme[opos+1]) msa->pp[idx][npos++] = msa->pp[idx][opos];
      msa->pp[idx][npos] = '\0';
    }
  }

  for (i = 0; i < msa->ngr; i++) {
    for (idx = 0; idx < msa->nseq; idx++) {
      if (msa->gr[i][idx]) {
        for (opos = 0, npos = 0; opos < msa->alen; opos++)
          if (useme[opos+1]) msa->gr[i][idx][npos++] = msa->gr[i][idx][opos];
        msa->gr[i][idx][npos] = '\0';
      }
    }
  }

  if (msa->ss_cons) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->ss_cons[npos++] = msa->ss_cons[opos];
    msa->ss_cons[npos] = '\0';
  }

  if (msa->sa_cons) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->sa_cons[npos++] = msa->sa_cons[opos];
    msa->sa_cons[npos] = '\0';
  }

  if (msa->pp_cons) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->pp_cons[npos++] = msa->pp_cons[opos];
    msa->pp_cons[npos] = '\0';
  }

  if (msa->rf) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->rf[npos++] = msa->rf[opos];
    msa->rf[npos] = '\0';
  }

  if (msa->mm) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->mm[npos++] = msa->mm[opos];
    msa->mm[npos] = '\0';
  }

  for (i = 0; i < msa->ngc; i++) {
    for (opos = 0, npos = 0; opos < msa->alen; opos++)
      if (useme[opos+1]) msa->gc[i][npos++] = msa->gc[i][opos];
    msa->gc[i][npos] = '\0';
  }

  npos = 0;
  for (opos = 1; opos <= msa->alen; opos++)
    if (useme[opos]) npos++;
  msa->alen = npos;

  return eslOK;
}

int
esl_msa_MinimGapsSymconvert(ESL_MSA *msa, char *errbuf)
{
  int *useme = NULL;
  int apos, idx;
  int64_t nseqgap;
  int status;

  if (msa->flags & eslMSA_DIGITAL) ESL_EXCEPTION(eslEUNIMPLEMENTED, "esl_msa_MinimGapsSymconvert() only works on text mode alignments");
  if (msa->nseq == 0) return eslOK;

  ESL_ALLOC(useme, sizeof(int) * (msa->alen+1));

  for (apos = 1; apos <= msa->alen; apos++) {
    for (nseqgap = 0, idx = 0; idx < msa->nseq; idx++)
      if (strchr("-_.~", msa->aseq[idx][apos-1]) != NULL) nseqgap++;

    if (nseqgap == msa->nseq) useme[apos] = FALSE;
    else useme[apos] = TRUE;
  }

  if ((status = esl_msa_ColumnSubset(msa, errbuf, useme)) != eslOK) goto ERROR;

  for (idx = 0; idx < msa->nseq; idx++)
    for (apos = 0; apos < msa->alen; apos++)
      if (msa->aseq[idx][apos] == '.' || msa->aseq[idx][apos] == '_' || msa->aseq[idx][apos] == '~')
        msa->aseq[idx][apos] = '-';

  free(useme);
  return eslOK;

 ERROR:
  if (useme) free(useme);
  return status;
}

int
esl_msa_Sample(ESL_RANDOMNESS *rng, const ESL_MSA *msa, int *ret_sampled, ESL_MSA **ret_newmsa)
{
  int *assignment = NULL;
  int *ct = NULL;
  int *useme = NULL;
  ESL_MSA *newmsa = NULL;
  int M;
  int idx;
  int i;
  int status;

  *ret_sampled = 0;
  *ret_newmsa = NULL;

  ESL_ALLOC(assignment, sizeof(int) * msa->nseq);
  ESL_ALLOC(ct, sizeof(int) * msa->nseq);
  ESL_ALLOC(useme, sizeof(int) * msa->nseq);

  for (idx = 0; idx < msa->nseq; idx++)
    useme[idx] = FALSE;

  for (idx = 0; idx < msa->nseq; idx++)
    ct[idx] = 0;

  for (idx = 0; idx < msa->nseq; idx++) {
    assignment[idx] = esl_rnd_Roll(rng, msa->nseq);
    ct[assignment[idx]]++;
  }

  M = 0;
  for (i = 0; i < msa->nseq; i++)
    if (ct[i]) M++;

  for (idx = 0; idx < msa->nseq; idx++)
    useme[assignment[idx]] = TRUE;

  if ((status = esl_msa_SequenceSubset(msa, useme, &newmsa)) != eslOK) goto ERROR;

  *ret_sampled = M;
  *ret_newmsa = newmsa;
  free(assignment);
  free(ct);
  free(useme);
  return eslOK;

 ERROR:
  if (assignment) free(assignment);
  if (ct) free(ct);
  if (useme) free(useme);
  if (newmsa) esl_msa_Destroy(newmsa);
  return status;
}

int
esl_msa_ReasonableRF(ESL_MSA *msa, double symfrac, const char *syms, const char *gapsyms, char *rfline)
{
  int *ct = NULL;
  int apos;
  int idx;
  char rfchar;
  int status;

  if (msa->flags & eslMSA_DIGITAL) ESL_EXCEPTION(eslEINVAL, "esl_msa_ReasonableRF() only works on text mode alignments");

  ESL_ALLOC(ct, sizeof(int) * 256);

  for (apos = 0; apos < msa->alen; apos++) {
    for (idx = 0; idx < 256; idx++) ct[idx] = 0;
    for (idx = 0; idx < msa->nseq; idx++)
      ct[(int) msa->aseq[idx][apos]]++;

    for (idx = 0; syms[idx] != '\0'; idx++)
      if ((double) ct[(int) syms[idx]] / (double) msa->nseq >= symfrac) break;

    if (syms[idx] != '\0') rfchar = 'x';
    else rfchar = '.';

    rfline[apos] = rfchar;
  }
  rfline[apos] = '\0';

  free(ct);
  return eslOK;

 ERROR:
  if (ct) free(ct);
  return status;
}

int
esl_msa_MarkFragments(ESL_MSA *msa, double fragthresh)
{
  int *span = NULL;
  int *ngap = NULL;
  int idx;
  int apos;
  int status;

  ESL_ALLOC(span, sizeof(int) * msa->nseq);
  ESL_ALLOC(ngap, sizeof(int) * msa->nseq);

  for (idx = 0; idx < msa->nseq; idx++) {
    span[idx] = 0;
    ngap[idx] = 0;
  }

  if (msa->flags & eslMSA_DIGITAL) {
    for (idx = 0; idx < msa->nseq; idx++) {
      for (apos = 1; apos <= msa->alen; apos++) {
        if (esl_abc_XIsResidue(msa->abc, msa->ax[idx][apos])) {
          if (span[idx] == 0) span[idx] = apos;
          span[idx] = apos - span[idx] + 1;
        } else if (span[idx] > 0 && esl_abc_XIsGap(msa->abc, msa->ax[idx][apos])) {
          ngap[idx]++;
        }
      }
    }
  } else {
    for (idx = 0; idx < msa->nseq; idx++) {
      for (apos = 0; apos < msa->alen; apos++) {
        if (isalpha(msa->aseq[idx][apos])) {
          if (span[idx] == 0) span[idx] = apos+1;
          span[idx] = apos+1 - span[idx] + 1;
        } else if (span[idx] > 0 && strchr("-_.", msa->aseq[idx][apos])) {
          ngap[idx]++;
        }
      }
    }
  }

  for (idx = 0; idx < msa->nseq; idx++) {
    if (span[idx] == 0) continue;
    if ((double) ngap[idx] / (double) span[idx] <= fragthresh) continue;

    if ((status = esl_msa_FormatSeqName(msa, idx, "%s_F", msa->sqname[idx])) != eslOK) goto ERROR;
  }

  free(span);
  free(ngap);
  return eslOK;

 ERROR:
  if (span) free(span);
  if (ngap) free(ngap);
  return status;
}

int
esl_msa_SequenceMask(const ESL_MSA *msa, int **ret_mask)
{
  int *mask = NULL;
  int idx, apos;
  int status;

  ESL_ALLOC(mask, sizeof(int) * msa->nseq);
  for (idx = 0; idx < msa->nseq; idx++)
    mask[idx] = 0;

  if (msa->flags & eslMSA_DIGITAL) {
    for (idx = 0; idx < msa->nseq; idx++)
      for (apos = 1; apos <= msa->alen; apos++)
        if (esl_abc_XIsResidue(msa->abc, msa->ax[idx][apos]))
          mask[idx]++;
  } else {
    for (idx = 0; idx < msa->nseq; idx++)
      for (apos = 0; apos < msa->alen; apos++)
        if (isalpha(msa->aseq[idx][apos]))
          mask[idx]++;
  }

  *ret_mask = mask;
  return eslOK;

 ERROR:
  if (mask) free(mask);
  *ret_mask = NULL;
  return status;
}

int
esl_msa_RemoveBrokenBasepairs(ESL_MSA *msa, int *ret_nremoved)
{
  int *ct = NULL;
  int apos;
  int nremoved = 0;
  int status;

  if (msa->ss_cons == NULL) { *ret_nremoved = 0; return eslOK; }

  if ((status = esl_wuss2ct(msa->ss_cons, msa->alen, &ct)) != eslOK) goto ERROR;

  for (apos = 0; apos < msa->alen; apos++) {
    if (ct[apos] != -1 && ct[apos] > apos) {
      if (msa->rf && (esl_abc_CIsGap(msa->rf[apos]) || esl_abc_CIsGap(msa->rf[ct[apos]]))) {
        msa->ss_cons[apos] = '.';
        msa->ss_cons[ct[apos]] = '.';
        nremoved++;
      }
    }
  }

  free(ct);
  *ret_nremoved = nremoved;
  return eslOK;

 ERROR:
  if (ct) free(ct);
  return status;
}

int
esl_msa_Write(FILE *fp, const ESL_MSA *msa, int format)
{
  switch (format) {
  case eslMSAFILE_STOCKHOLM: return esl_msafile_stockholm_Write(fp, msa, eslMSAFILE_STOCKHOLM);
  case eslMSAFILE_PFAM: return esl_msafile_stockholm_Write(fp, msa, eslMSAFILE_PFAM);
  case eslMSAFILE_A2M: return esl_msafile_a2m_Write(fp, msa);
  case eslMSAFILE_PSIBLAST: return esl_msafile_psiblast_Write(fp, msa);
  case eslMSAFILE_SELEX: return esl_msafile_selex_Write(fp, msa);
  case eslMSAFILE_AFA: return esl_msafile_afa_Write(fp, msa);
  case eslMSAFILE_CLUSTAL: return esl_msafile_clustal_Write(fp, msa);
  case eslMSAFILE_CLUSTALLIKE: return esl_msafile_clustal_Write(fp, msa);
  case eslMSAFILE_PHYLIP: return esl_msafile_phylip_Write(fp, msa, eslMSAFILE_PHYLIP);
  case eslMSAFILE_PHYLIPS: return esl_msafile_phylip_Write(fp, msa, eslMSAFILE_PHYLIPS);
  default: ESL_EXCEPTION(eslEINVAL, "no such alignment file format code");
  }
}

int
esl_msa_EncodeFormat(char *fmtstring)
{
  if (strcasecmp(fmtstring, "stockholm") == 0) return eslMSAFILE_STOCKHOLM;
  else if (strcasecmp(fmtstring, "pfam") == 0) return eslMSAFILE_PFAM;
  else if (strcasecmp(fmtstring, "a2m") == 0) return eslMSAFILE_A2M;
  else if (strcasecmp(fmtstring, "psiblast") == 0) return eslMSAFILE_PSIBLAST;
  else if (strcasecmp(fmtstring, "selex") == 0) return eslMSAFILE_SELEX;
  else if (strcasecmp(fmtstring, "afa") == 0) return eslMSAFILE_AFA;
  else if (strcasecmp(fmtstring, "clustal") == 0) return eslMSAFILE_CLUSTAL;
  else if (strcasecmp(fmtstring, "clustallike") == 0) return eslMSAFILE_CLUSTALLIKE;
  else if (strcasecmp(fmtstring, "phylip") == 0) return eslMSAFILE_PHYLIP;
  else if (strcasecmp(fmtstring, "phylips") == 0) return eslMSAFILE_PHYLIPS;
  else return eslMSAFILE_UNKNOWN;
}

